rng=np.random.default_rng(9173)
N=48000;Nt=12000
X=rng.uniform(0,10,(N+Nt,20));X[:,0]=rng.uniform(-4,3,N+Nt);X[:,1:10]=rng.integers(0,2,(N+Nt,9))
y=predict(X).ravel()
def fit(B):
 c=np.linalg.lstsq(B[:N],y[:N],rcond=1e-10)[0];r=y-B@c
 print('features',len(c),'RMSE train/test',np.sqrt(np.mean(r[:N]**2)),np.sqrt(np.mean(r[N:]**2)),'R2',1-np.mean(r[N:]**2)/np.var(y[N:]),'P-MAE',np.mean(np.abs(1/(1+np.exp(-y[N:]))-1/(1+np.exp(-(B@c)[N:])))))
 return c,r
for num in [1,2,4]:
 cols=[np.ones(len(X))];meta=[('intercept',)];g=[];mt=[]
 for j in range(20):
  lo,hi=(-4,3) if j==0 else (0,1) if j<10 else (0,10)
  knots=[] if 1<=j<10 else (list(np.linspace(lo,hi,num+2)[1:-1]) if j!=12 else [1,2,3,4,5,6,7,8,9])
  z=np.column_stack([X[:,j]]+[np.maximum(X[:,j]-k,0) for k in knots]);m=[('linear',j)]+[('hinge',j,float(k)) for k in knots]
  center=z[:N].mean(axis=0);q,r=np.linalg.qr(z[:N]-center,mode='reduced');z=(z-center)@np.linalg.inv(r)*np.sqrt(N)
  g.append(z);mt.append(m)
  for a in range(z.shape[1]):cols.append(z[:,a]);meta.append(('main',j,a))
 for j in range(20):
  for k in range(j+1,20):
   for a in range(g[j].shape[1]):
    for b in range(g[k].shape[1]):
     cols.append(g[j][:,a]*g[k][:,b]);meta.append(('inter',j,k,a,b))
 B=np.column_stack(cols);c,r=fit(B)
 print('num',num,'top interaction coeffs',sorted([(meta[i],round(float(c[i]),4)) for i in range(len(meta)) if meta[i][0]=='inter'],key=lambda t:abs(t[1]),reverse=True)[:60])

